package gofastooxml_test

import (
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/AOShei/go-fast-ooxml/internal/ooxmltest"
)

// The comparison table in the README is generated by bench/compare.py
// from its measurements, never typed: it must be the table of
// bench/comparison.md, which the same run writes.
func TestReadmeComparison(t *testing.T) {
	const begin, end = "<!-- comparison:begin -->", "<!-- comparison:end -->"
	table := func(name string) string {
		data, err := os.ReadFile(filepath.Join(ooxmltest.Root(t), filepath.FromSlash(name)))
		if err != nil {
			t.Fatal(err)
		}
		text := strings.ReplaceAll(string(data), "\r\n", "\n")
		_, rest, found := strings.Cut(text, begin)
		inner, _, closed := strings.Cut(rest, end)
		if !found || !closed {
			t.Fatalf("%s has no comparison markers", name)
		}
		return strings.TrimSpace(inner)
	}
	readme, generated := table("README.md"), table("bench/comparison.md")
	if readme != generated {
		t.Errorf("the comparison table in README.md is not the one in bench/comparison.md; run bench/compare.py --write\nREADME:\n%s\ngenerated:\n%s", readme, generated)
	}
	if rows := strings.Count(generated, "\n"); rows < 8 || !strings.Contains(generated, "this library") {
		t.Errorf("the generated table has %d rows:\n%s", rows, generated)
	}
}
